create table wksp_dtesc.sgt_evento_evidencia (
    id                  number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    evento_id           number not null enable,
    evento_accion_id    number,
    evento_subtarea_id  number,
    tipo_evidencia      varchar2(50 byte) not null enable,
    categoria           varchar2(100 byte),
    nombre_archivo      varchar2(255 byte) not null enable,
    ruta_almacenamiento varchar2(500 byte) not null enable,
    descripcion         varchar2(500 byte),
    cargado_por         varchar2(255 byte) not null enable,
    fecha_carga         timestamp(6) default systimestamp not null enable,
    creado_por          varchar2(255 byte),
    creado_el           timestamp(6) default systimestamp,
    archivo_blob        blob,
    mime_type           varchar2(255 byte)
);

alter table wksp_dtesc.sgt_evento_evidencia
    add constraint chk_sgt_evento_evidencia_tipo
        check ( tipo_evidencia in ( 'FOTO', 'VIDEO', 'PDF', 'KMZ', 'OTRO' ) ) enable;

alter table wksp_dtesc.sgt_evento_evidencia
    add constraint pk_sgt_evento_evidencia primary key ( id )
        using index enable;


